  function askInvite(){showModal('Invite a teammate','Add a person to your local workspace team.',`<form id="invite-form"><div class="field"><label>Name</label><input name="name" required maxlength="80"></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role"><option>Editor</option><option>Contributor</option></select></div><div class="notice">This browser-only preview cannot send email invitations. A teammate added here is visible only in this browser.</div><div class="form-footer"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button button-primary">Add teammate</button></div></form>`)}
  const aliases={date:['date','publish date','published date','post date','creation time','date posted'],time:['publish time','published time','post time','time published','time'],content:['content','post','post text','message','caption','title','description'],platform:['platform','account platform','channel','network'],reach:['reach','accounts reached','people reached','post reach'],impressions:['impressions','impression'],views:['views','video views','plays'],likes:['likes','reactions','like count'],comments:['comments','comment count'],shares:['shares','share count'],saves:['saves','saved'],clicks:['clicks','link clicks'],engagement:['engagement','total interactions','interactions','engagements'],engagementRate:['engagement rate','engagement rate %','rate'],follows:['follows','followers','new follows'],profileVisits:['profile visits','visits'],hashtags:['hashtags','hash tags','tags']};
  const metricNames={date:'Date',time:'Publish Time',content:'Content',platform:'Platform',reach:'Reach',impressions:'Impressions',views:'Views',likes:'Likes / Reactions',comments:'Comments',shares:'Shares',saves:'Saves',clicks:'Clicks',engagement:'Engagement',engagementRate:'Engagement Rate',follows:'Follows',profileVisits:'Profile Visits',hashtags:'Hashtags'};
  function parseCSV(text){const out=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))out.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))out.push(row);return out}
  function guessMap(headers){const map={};for(const [field,names] of Object.entries(aliases)){let found=headers.findIndex(h=>names.includes(h.toLowerCase().trim()));if(found<0)found=headers.findIndex(h=>names.some(a=>h.toLowerCase().includes(a)));if(found>=0)map[field]=found}return map}
